[
  {
    "sys_consequence_reasoning": "Five people getting home against one person not making it",
    "pd_personal_consequence_anxiety": "though it scares me badly",
    "pda_responsibility": "If I step forward, that outcome is mine; I chose it",
    "pda_explicit_no_harm_regret": "I wouldn't feel sorry about hurting anyone",
    "pda_self_consequence_regret": "What I'd mourn is my own share"
  },
  {
    "pda_responsibility": "I can't pretend my silence plays no part in that",
    "pda_practical_counterfactual": "I kept quiet when I could have spoken up",
    "pda_explicit_no_harm_regret": "I don't regret any harm in holding my place",
    "pda_self_consequence_regret": "What gnaws at me is myself afterward: people remembering"
  },
  {
    "pd_decision_conflict": "I honestly can't settle it, and that frightens me",
    "pda_responsibility": "Whatever happens, part of it comes from me, from hesitating",
    "pda_explicit_no_harm_regret": "I wouldn't carry remorse over harming someone",
    "pda_self_consequence_regret": "What I'd grieve is the life I'd be giving up"
  },
  {
    "pda_responsibility": "I'd be the one who decided it, and I accept that",
    "pda_explicit_no_harm_regret": "Would I feel bad about causing harm? No.",
    "pda_self_consequence_regret": "The regret I can see coming is purely selfish",
    "pd_personal_consequence_anxiety": "That's what makes my hands shake."
  },
  {
    "pda_practical_counterfactual": "I'd push for drawing lots instead of anyone volunteering",
    "pda_responsibility": "If it's my idea, then I own whatever the draw does",
    "pda_explicit_no_harm_regret": "I won't hold remorse for that harm",
    "sys_fairness_reciprocity": "a fair draw is the least bad option",
    "pda_self_consequence_regret": "regret losing my life, obviously"
  },
  {
    "pd_personal_consequence_anxiety": "saying that out loud makes me uneasy",
    "pda_responsibility": "By not volunteering I'm part of why someone else gets left",
    "pda_explicit_no_harm_regret": "But I don't regret the harm of keeping my seat",
    "pda_self_consequence_regret": "My worry is what it costs me: my reputation"
  },
  {
    "pd_personal_consequence_anxiety": "though my voice would probably crack doing it",
    "sys_rule_justification": "I'm the one person whose choice I actually control",
    "pda_responsibility": "So it's my call and my responsibility",
    "pda_explicit_no_harm_regret": "I'm not sorry for any harm there",
    "pda_self_consequence_regret": "What I'd regret is personal: the time I wasted before this"
  },
  {
    "pd_decision_conflict": "I can't give a clean yes",
    "pda_responsibility": "I know that delay is my own doing",
    "pda_explicit_no_harm_regret": "I wouldn't regret any harm from staying",
    "pda_self_consequence_regret": "But I'd regret, sharply, what I'm losing"
  },
  {
    "pda_responsibility": "My choosing to stay in the boat is one reason... I'll own that",
    "pda_explicit_no_harm_regret": "I don't feel remorse over harming anyone by it",
    "pda_self_consequence_regret": "The regret I'd expect is about me: losing friends' respect"
  },
  {
    "pd_personal_consequence_anxiety": "I'm terrified even imagining it",
    "sys_rule_justification": "feels like the only choice I have any right to make",
    "pda_explicit_no_harm_regret": "There's no harm to others in that, so no remorse",
    "pda_self_consequence_regret": "My regret would be about me, losing my whole future"
  }
]
